SECRETS = [
    ("db-password", 95, 90),
    ("api-key-payments", 30, 90),
    ("tls-cert", 400, 365),
    ("signing-key", 180, 365),
]

def rotation_status(name, age_days, max_age_days):
    if age_days > max_age_days:
        return f"{name}: ROTATE ({age_days}d > {max_age_days}d)"
    return f"{name}: OK"

overdue = 0
for name, age, max_age in SECRETS:
    print(rotation_status(name, age, max_age))
    if age > max_age:
        overdue += 1

print(f"Rotation required: {overdue}/{len(SECRETS)}")
